example_item.example_item_data:
schema = protobuf.load([modulepath('protobuf'), '/tests/data/sensor_stream.proto']);
filename = [tempdir(), 'stream.bin'];
protobuf.write(schema, 'SensorSample', filename, struct('timestamp_ms', {1, 2}), 'Delimited', true);
protobuf.write(schema, 'SensorSample', filename, struct('timestamp_ms', 3), 'Delimited', true, 'Append', true);
C = protobuf.read(schema, 'SensorSample', filename, 'Delimited', true, 'Layout', 'columns');
C.timestamp_ms
delete(filename);
